SELECT p.id, p.name, p.company_id as companyId, p.os_type as osType, c.name as companyName, p.creator, p.create_time, p.updater, p.update_time, p.deleted, p.tenant_id FROM dsp_product as p LEFT JOIN dsp_company as c ON c.id = p.company_id
AND p.name LIKE CONCAT('%', #{reqVO.name}, '%')
AND p.company_id = #{reqVO.companyId}
AND p.os_type = #{reqVO.osType}
AND p.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
ORDER BY p.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM dsp_product as p
    LEFT JOIN dsp_company as c
        ON c.id = p.company_id



        AND p.name LIKE CONCAT('%', #{reqVO.name}, '%')


        AND p.company_id = #{reqVO.companyId}


        AND p.os_type = #{reqVO.osType}


        AND p.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

SELECT COUNT(*)
FROM dsp_product
WHERE company_id = #{companyId}
  AND name = #{name}

  AND id != #{excludeId}
